import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.BN3Eol-0.js";const g=JSON.parse('{"title":"PRD-037 · Names in 13 languages: a public glossary page","description":"","frontmatter":{},"headers":[],"relativePath":"prd/PRD-037.md","filePath":"prd/PRD-037.md"}'),s={name:"prd/PRD-037.md"};function r(i,e,l,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="prd-037-·-names-in-13-languages-a-public-glossary-page" tabindex="-1">PRD-037 · Names in 13 languages: a public glossary page <a class="header-anchor" href="#prd-037-·-names-in-13-languages-a-public-glossary-page" aria-label="Permalink to &quot;PRD-037 · Names in 13 languages: a public glossary page&quot;">​</a></h1><blockquote><p>Status · Draft, for operator sign-off Date · 2026-10-22 Owner · Marko Closes into · #612 Builds on · <code>scripts/i18n-tools/native-terms.json</code> (the translation glossary) · <code>/sourcing</code> (the model for a public, data-driven transparency page) · the naming rules (science-terms-native, origin-language rule, <code>src/lib/name-origins.js</code>)</p></blockquote><blockquote><p><strong>Why this is a PRD.</strong> It adds a public route built from an internal translation tool, and it publishes the site&#39;s naming rules as a promise readers can check. That needs agreement on what is shown, how gaps are handled and how readers report a wrong form before anything is built.</p></blockquote><h2 id="_1-·-what" tabindex="-1">1 · What <a class="header-anchor" href="#_1-·-what" aria-label="Permalink to &quot;1 · What&quot;">​</a></h2><p>A page, <code>/names</code>, listing every name in the glossary with its form in each of Orrery&#39;s 14 languages.</p><ul><li><strong>Rows:</strong> one per name. Columns: English, then the 13 locales. The reader&#39;s own language is shown first after English.</li><li><strong>Categories as filters:</strong> people (302), stars and constellations (235), surface features (89), bodies (82), places (24), facilities (14), agencies (7), stations (2). 755 names on 2026-10-22.</li><li><strong>Search:</strong> one box matching any form in any script (typing Кеплер, ケプラー or Kepler finds the same row).</li><li><strong>Wikidata link</strong> per row where the glossary has an id (every star and agency, 289 of 302 people, 43 of 82 bodies; few features and places). It opens Wikidata, which links to every language&#39;s Wikipedia.</li><li><strong>The rules, in plain words, at the top:</strong> science terms, places and people are written the way each country&#39;s schools and agencies write them; built things (vehicles, missions) keep their name except in their origin language; agencies have a local form only in their own language.</li><li><strong>&quot;Report a wrong form&quot;</strong> link per row (§4).</li></ul><h2 id="_2-·-empty-cells-what-they-mean-and-what-we-show" tabindex="-1">2 · Empty cells: what they mean and what we show <a class="header-anchor" href="#_2-·-empty-cells-what-they-mean-and-what-we-show" aria-label="Permalink to &quot;2 · Empty cells: what they mean and what we show&quot;">​</a></h2><p>The glossary stores a form only where it differs from English, so an empty cell means one of three things:</p><table tabindex="0"><thead><tr><th>Case</th><th>Example</th><th>Shown as</th></tr></thead><tbody><tr><td>Same as English (Latin-script languages)</td><td>Houston in German; Michael Collins in French</td><td>the English form, greyed</td></tr><tr><td>Agency, by rule</td><td>Roscosmos has only <code>ru</code> Роскосмос</td><td>the English form, greyed</td></tr><tr><td><strong>Real gap</strong> (non-Latin script missing)</td><td>Hayley Arceneaux has no Serbian or Korean; Chris Sembroski no Arabic, Korean, Serbian; most constellations no Hindi</td><td>must not ship empty</td></tr></tbody></table><p>On 2026-10-22, 277 entries have an empty non-Latin cell; 7 are agencies (by rule), so 270 are real gaps: 131 people, 128 stars and constellations, 10 bodies, 1 place.</p><p><strong>Proposal:</strong> fill the real gaps by hand before the page ships (free route, same sourcing rules as the glossary: each form as that language&#39;s universities, schools or space agency write it; unsure → search native pages). Serbian is the operator&#39;s call.</p><p>Not checked yet: how the site writes those names in its pages today. The translated text may already carry a form where the glossary is empty; filling the glossary from the site&#39;s own form, where one exists, keeps one name per language.</p><h2 id="_3-·-where-the-name-appears-optional-phase-2" tabindex="-1">3 · Where the name appears (optional, phase 2) <a class="header-anchor" href="#_3-·-where-the-name-appears-optional-phase-2" aria-label="Permalink to &quot;3 · Where the name appears (optional, phase 2)&quot;">​</a></h2><p>Each row could list the pages that use the name. That needs a scan of the content files per locale. Phase 2, if the operator wants it; phase 1 ships without it.</p><h2 id="_4-·-reporting-a-wrong-form" tabindex="-1">4 · Reporting a wrong form <a class="header-anchor" href="#_4-·-reporting-a-wrong-form" aria-label="Permalink to &quot;4 · Reporting a wrong form&quot;">​</a></h2><p>Per row, a link that opens a prefilled email (or GitHub issue form) naming the entry, the locale and the current form. No accounts, no form backend. Corrections land in <code>native-terms.json</code> like any other edit.</p><h2 id="_5-·-translation-and-design" tabindex="-1">5 · Translation and design <a class="header-anchor" href="#_5-·-translation-and-design" aria-label="Permalink to &quot;5 · Translation and design&quot;">​</a></h2><ul><li>Page chrome (title, rules text, filters, column labels, the report link) translated into 13 locales by hand.</li><li>The table is wide (15 columns). Desktop: horizontal scroll with English pinned. Phone: one card per name, the reader&#39;s language first, other languages folded.</li><li>RTL: Arabic cells right-to-left inside the table.</li><li>Linked from <code>/sourcing</code>, the colophon and the footer&#39;s About area.</li></ul><h2 id="_6-·-data-path" tabindex="-1">6 · Data path <a class="header-anchor" href="#_6-·-data-path" aria-label="Permalink to &quot;6 · Data path&quot;">​</a></h2><p><code>native-terms.json</code> stays the source of truth. A build step copies the display fields (forms, category, Wikidata id) to <code>static/data/names.json</code>, excluding <code>sources</code> and <code>_comment</code>. <code>validate-data</code> checks that no real gap remains (§2) once the fill is done, so the page cannot regress.</p><h2 id="_7-·-measurement" tabindex="-1">7 · Measurement <a class="header-anchor" href="#_7-·-measurement" aria-label="Permalink to &quot;7 · Measurement&quot;">​</a></h2><p>Umami: page views, searches (<code>search</code> event with <code>surface: names</code>, query length only, the existing pattern), report-link clicks.</p><h2 id="_8-·-done" tabindex="-1">8 · Done <a class="header-anchor" href="#_8-·-done" aria-label="Permalink to &quot;8 · Done&quot;">​</a></h2><ul><li><code>/names</code> renders all glossary entries with filters and search, desktop and phone, in all 14 locales.</li><li>No real gap left; <code>validate-data</code> enforces it.</li><li>e2e: search in three scripts finds one row; a category filter; the phone layout.</li></ul><h2 id="_9-·-non-goals" tabindex="-1">9 · Non-goals <a class="header-anchor" href="#_9-·-non-goals" aria-label="Permalink to &quot;9 · Non-goals&quot;">​</a></h2><ul><li><strong>Vehicle and mission names</strong> (<code>name-origins.js</code>) in phase 1. They follow a different rule (origin language only); a second table later if wanted.</li><li>Editing names on the page.</li><li>Pronunciation or audio.</li></ul><h2 id="_10-·-open-questions-for-the-operator" tabindex="-1">10 · Open questions for the operator <a class="header-anchor" href="#_10-·-open-questions-for-the-operator" aria-label="Permalink to &quot;10 · Open questions for the operator&quot;">​</a></h2><ol><li>Route name: <code>/names</code> (proposed) or under <code>/library</code>?</li><li>Report link: email or GitHub issue form?</li><li>Phase 2 (where each name appears): wanted?</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>#612</li><li><code>scripts/i18n-tools/native-terms.json</code>, <code>src/lib/name-origins.js</code></li><li><code>/sourcing</code> (<code>src/routes/sourcing/+page.svelte</code>): the transparency-page model</li></ul>',30)])])}const u=a(s,[["render",r]]);export{g as __pageData,u as default};
